/* Renewal Runway — stylesheet */

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --brand: #1a4fa0;
  --brand-dark: #133a7a;
  --accent: #e85d2e;
  --bg: #f5f7fb;
  --surface: #ffffff;
  --border: #d0d7e6;
  --text: #1c2235;
  --muted: #64718a;
  --error-bg: #fff4f2;
  --error-border: #f4a98a;
  --error-text: #b03a1a;
  --warn-bg: #fff8ec;
  --warn-border: #f5c842;
  --warn-text: #7a5000;
  --success-bg: #eef7ee;
  --success-border: #7ec87e;
  --success-text: #1e5e1e;
  --info-bg: #eef3fc;
  --info-border: #7daef5;
  --radius: 8px;
  --shadow: 0 2px 10px rgba(26,79,160,.10);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 32px 16px 48px;
}

header {
  width: 100%;
  max-width: 560px;
  margin-bottom: 28px;
}

header h1 {
  font-size: 1.55rem;
  font-weight: 700;
  color: var(--brand);
  letter-spacing: -0.02em;
}

header p {
  margin-top: 4px;
  font-size: 0.9rem;
  color: var(--muted);
}

main {
  width: 100%;
  max-width: 560px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Card */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px 24px 20px;
  box-shadow: var(--shadow);
}

.card h2 {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 16px;
}

/* Form groups */
.form-group {
  margin-bottom: 16px;
}
.form-group:last-child { margin-bottom: 0; }

label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 5px;
}

label .optional {
  font-weight: 400;
  color: var(--muted);
  font-size: 0.8rem;
}

input[type="text"],
input[type="number"],
input[type="date"],
select {
  width: 100%;
  padding: 9px 12px;
  border: 1.5px solid var(--border);
  border-radius: 6px;
  font-size: 0.95rem;
  color: var(--text);
  background: #fff;
  appearance: none;
  -webkit-appearance: none;
  transition: border-color 0.15s, box-shadow 0.15s;
  font-family: inherit;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(26,79,160,.15);
}

input.invalid {
  border-color: var(--error-border);
}
input.invalid:focus {
  box-shadow: 0 0 0 3px rgba(244,169,138,.2);
}

.field-error {
  margin-top: 5px;
  font-size: 0.8rem;
  color: var(--error-text);
  display: none;
}
.field-error.visible { display: block; }

/* Two-column row */
.row-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

/* Preset row */
.preset-row {
  display: flex;
  align-items: flex-end;
  gap: 10px;
}
.preset-row .form-group { flex: 1; margin-bottom: 0; }

/* Reset button */
.btn-reset {
  padding: 9px 18px;
  border: 1.5px solid var(--border);
  border-radius: 6px;
  background: #fff;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--muted);
  cursor: pointer;
  white-space: nowrap;
  transition: border-color 0.15s, color 0.15s;
  font-family: inherit;
}
.btn-reset:hover { border-color: var(--brand); color: var(--brand); }
.btn-reset:focus { outline: none; box-shadow: 0 0 0 3px rgba(26,79,160,.15); }

/* Results panel */
#results {
  min-height: 72px;
}

.result-inner {
  font-size: 0.9rem;
  color: var(--muted);
}

/* At-risk banner */
.banner-atrisk {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--warn-bg);
  border: 1px solid var(--warn-border);
  border-radius: 6px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--warn-text);
  margin-bottom: 14px;
}
.banner-atrisk::before {
  content: "⚠";
  font-size: 1rem;
  flex-shrink: 0;
}

/* Result states */
.result-met {
  padding: 14px 16px;
  background: var(--success-bg);
  border: 1px solid var(--success-border);
  border-radius: 6px;
  color: var(--success-text);
  font-weight: 600;
  font-size: 0.95rem;
}
.result-met::before { content: "✓ "; }

.result-passed {
  padding: 14px 16px;
  background: var(--error-bg);
  border: 1px solid var(--error-border);
  border-radius: 6px;
  color: var(--error-text);
  font-weight: 600;
  font-size: 0.95rem;
}

.result-pace-wrap {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.result-main {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--brand);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.result-urgency-main {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--brand);
  line-height: 1.3;
}

.result-secondary {
  display: flex;
  gap: 20px;
  margin-top: 2px;
}

.result-secondary span {
  font-size: 0.85rem;
  color: var(--muted);
  font-weight: 500;
}

.result-secondary span strong {
  color: var(--text);
  font-weight: 700;
}

/* Empty / hint */
.result-hint {
  padding: 14px 16px;
  background: var(--info-bg);
  border: 1px solid var(--info-border);
  border-radius: 6px;
  color: var(--muted);
  font-size: 0.9rem;
}

/* Footer */
footer {
  margin-top: 32px;
  font-size: 0.78rem;
  color: var(--muted);
  text-align: center;
}

/* Mobile */
@media (max-width: 480px) {
  .row-2 { grid-template-columns: 1fr; }
  .result-main { font-size: 1.4rem; }
  .card { padding: 18px 16px; }
}

