/* Renewal Runway — stylesheet */

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --brand: #1a4fa0;
  --brand-dark: #133a7a;
  --accent: #e85d2e;
  --bg: #f5f7fb;
  --surface: #ffffff;
  --border: #d0d7e6;
  --text: #1c2235;
  --muted: #64718a;
  --error-bg: #fff4f2;
  --error-border: #f4a98a;
  --error-text: #b03a1a;
  --warn-bg: #fff8ec;
