  font-weight: 500;
}

.result-secondary span strong {
  color: var(--text);
  font-weight: 700;
}

/* Empty / hint */
.result-hint {
  padding: 14px 16px;
  background: var(--info-bg);
  border: 1px solid var(--info-border);
  border-radius: 6px;
  color: var(--muted);
  font-size: 0.9rem;
}

