.result-pace-wrap--urgency .result-urgency-main {
  color: var(--warn-text);
}

/* Results card border by state */
#results.results--urgency {
  border-color: var(--warn-border);
}

#results.results--atrisk {
  border-color: var(--error-border);
}

/* Footer */
footer {
  margin-top: 32px;
  font-size: 0.78rem;
  color: var(--muted);
  text-align: center;
}

/* Mobile */
@media (max-width: 480px) {
  .row-2 { grid-template-columns: 1fr; }
  .result-main { font-size: 1.7rem; }
  .card { padding: 18px 16px; }
}

