  function setError(el, errEl, msg) {
    if (msg) {
      el.classList.add('invalid');
      errEl.textContent = msg;
      errEl.classList.add('visible');
    } else {
      el.classList.remove('invalid');
      errEl.textContent = '';
      errEl.classList.remove('visible');
    }
  }

  // ── Render ───────────────────────────────────────────────────────────────

  function render() {
    var reqVal  = elRequired.value;
    var earnVal = elEarned.value;
    var endVal  = elEndDate.value;
    var fromVal = elFromDate.value;

    var r = calculate(reqVal, earnVal, endVal, fromVal);

    // Show/clear field errors
    setError(elRequired, elErrReq,   r.errors.required);
    setError(elEarned,   elErrEarn,  r.errors.earned);
    setError(elEndDate,  elErrEnd,   r.errors.endDate);
    setError(elFromDate, elErrFrom,  r.errors.fromDate);

    // Update results card border to reflect severity
    elResults.className = 'card';
    if (r.isAtRisk) elResults.classList.add('results--atrisk');
    else if (r.state === 'urgency') elResults.classList.add('results--urgency');

    var html = '';

    if (r.state === 'empty') {
      html = '<div class="result-hint">Enter credits required and your cycle end date to see your pace.</div>';

    } else if (r.state === 'error') {
      html = '<div class="result-hint">Fix the highlighted field to see your pace.</div>';

    } else if (r.state === 'met') {
      var msg;
      if (r.extraDisplay !== null) {
        msg = 'Requirement met. You have ' + r.earnedDisplay + ' of ' + r.requiredDisplay
              + ' credits (' + r.extraDisplay + ' extra).';
      } else {
        msg = 'Requirement met. You have ' + r.earnedDisplay + ' of ' + r.requiredDisplay + ' credits.';
      }
      html = '<div class="result-met">' + esc(msg) + '</div>';

    } else if (r.state === 'passed') {
      var daysAgoStr = r.daysAgo === 1 ? '1 day ago' : r.daysAgo + ' days ago';
      html = '<div class="result-passed">Cycle ended on ' + esc(r.endDateDisplay)
             + ' (' + daysAgoStr + ').</div>';

    } else if (r.state === 'urgency') {
      var warnHtml = r.isAtRisk
        ? '<div class="banner-atrisk">At risk: this pace exceeds 40 credits per week.</div>'
        : '';
      var mainMsg;
      if (r.daysLeft === 1) {
        mainMsg = 'You need ' + r.remainingDisplay
                  + (r.remainingDisplay === '1' ? ' credit' : ' credits') + ' today.';
      } else {
        mainMsg = 'You need ' + r.remainingDisplay
                  + (r.remainingDisplay === '1' ? ' credit' : ' credits')
                  + ' in the next ' + r.daysLeft + ' days.';
      }
      var remLabel = r.remainingDisplay === '1' ? '1 credit remaining' : r.remainingDisplay + ' credits remaining';
      var dayLabel = r.daysLeft === 1 ? '1 day left' : r.daysLeft + ' days left';
      var urgencyClass = r.isAtRisk ? 'result-pace-wrap result-pace-wrap--atrisk' : 'result-pace-wrap result-pace-wrap--urgency';
      html = warnHtml
        + '<div class="' + urgencyClass + '">'
        + progressBar(r.earnedUnits, r.reqUnits)
        + '<div class="result-urgency-main">' + esc(mainMsg) + '</div>'
        + '<div class="result-secondary">'
        + '<span><strong>' + esc(remLabel) + '</strong></span>'
        + '<span><strong>' + esc(dayLabel) + '</strong></span>'
        + '</div></div>';

    } else if (r.state === 'pace') {
      var warnHtml2 = r.isAtRisk
        ? '<div class="banner-atrisk">At risk: this pace exceeds 40 credits per week.</div>'
        : '';
      var paceLabel = r.paceDisplay === '1' ? '1 credit per week' : r.paceDisplay + ' credits per week';
      var remLabel2 = r.remainingDisplay === '1' ? '1 credit remaining' : r.remainingDisplay + ' credits remaining';
      var dayLabel2 = r.daysLeft === 1 ? '1 day left' : r.daysLeft + ' days left';
      var paceClass = r.isAtRisk ? 'result-pace-wrap result-pace-wrap--atrisk' : 'result-pace-wrap';
      html = warnHtml2
        + '<div class="' + paceClass + '">'
        + progressBar(r.earnedUnits, r.reqUnits)
        + '<div class="result-main">' + esc(paceLabel) + '</div>'
        + '<div class="result-secondary">'
        + '<span><strong>' + esc(remLabel2) + '</strong></span>'
        + '<span><strong>' + esc(dayLabel2) + '</strong></span>'
        + '</div></div>';
    }

    elContent.innerHTML = html;
  }

  function esc(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function progressBar(earnedUnits, reqUnits) {
    var pct = reqUnits > 0 ? Math.min(100, Math.round(earnedUnits / reqUnits * 100)) : 0;
    var label = formatCredits(earnedUnits) + ' of ' + formatCredits(reqUnits) + ' credits earned';
    return '<div class="progress-label">' + esc(label) + '</div>'
      + '<div class="progress-wrap" role="progressbar" aria-valuenow="' + pct
      + '" aria-valuemin="0" aria-valuemax="100" aria-label="' + esc(label) + '">'
      + '<div class="progress-bar" style="width:' + pct + '%"></div>'
      + '</div>';
  }

  // ── Preset selector ──────────────────────────────────────────────────────

  var suppressPresetSwitch = false;

  elPreset.addEventListener('change', function () {
    var val = this.value;
    if (val !== '') {
      suppressPresetSwitch = true;
      elRequired.value = val;
      suppressPresetSwitch = false;
    }
    render();
  });

  elRequired.addEventListener('input', function () {
    if (!suppressPresetSwitch) {
      elPreset.value = '';
    }
    render();
  });

  // ── Live update on other fields ──────────────────────────────────────────

  elEarned.addEventListener('input', render);
  elEndDate.addEventListener('change', render);
  elFromDate.addEventListener('change', render);

  // ── Reset ────────────────────────────────────────────────────────────────

  elReset.addEventListener('click', function () {
    elPreset.value    = '';
    elRequired.value  = '';
    elEarned.value    = '0';
    elEndDate.value   = '';
    elFromDate.value  = todayISO();
    render();
  });

  // ── Initialise ───────────────────────────────────────────────────────────

  elEarned.value   = '0';
  elFromDate.value = todayISO();
  render();

}());
</script>

