    'Done': 'badge-done', 'On track': 'badge-on-track', 'Urgent': 'badge-urgent',
    'At risk': 'badge-at-risk', 'Lapsed': 'badge-lapsed',
    'Invalid': 'badge-invalid', 'Incomplete': 'badge-incomplete',
  };
  return map[badge] || 'badge-incomplete';
}

function resultLine(item) {
  var r = item.result;
  if (item.badge === 'Incomplete') return '';
  if (item.badge === 'Invalid') {
    var firstErr = r.errors.required || r.errors.earned || r.errors.endDate || r.errors.fromDate || '';
    return '<div class="team-result-error">' + esc(firstErr) + '</div>';
  }
  if (r.state === 'met') {
    var msg = 'Requirement met. ' + r.earnedDisplay + ' of ' + r.requiredDisplay + ' credits';
    if (r.extraDisplay) msg += ' (' + r.extraDisplay + ' extra)';
    return '<div class="team-result-line">' + esc(msg + '.') + '</div>';
  }
  if (r.state === 'passed') {
    var dStr = r.daysAgo === 1 ? '1 day ago' : r.daysAgo + ' days ago';
    return '<div class="team-result-line">' + esc('Cycle ended ' + dStr + '.') + '</div>';
  }
  if (r.state === 'urgency') {
    var cStr = r.daysLeft === 1
      ? esc(r.remainingDisplay) + ' credit' + (r.remainingDisplay === '1' ? '' : 's') + ' needed today'
      : esc(r.remainingDisplay) + ' credit' + (r.remainingDisplay === '1' ? '' : 's') + ' in ' + r.daysLeft + ' days';
    return '<div class="team-result-line">' + cStr + ' &middot; ' + esc(r.daysLeft + (r.daysLeft === 1 ? ' day left' : ' days left')) + '</div>';
  }
  // pace
  return '<div class="team-result-line">'
    + esc(r.paceDisplay + ' credit' + (r.paceDisplay === '1' ? '' : 's') + '/week')
    + ' &middot; ' + esc(r.remainingDisplay + ' remaining')
    + ' &middot; ' + esc(r.daysLeft + (r.daysLeft === 1 ? ' day left' : ' days left'))
    + '</div>';
}

// ── Render results ──────────────────────────────────────────────────────

function renderResults() {
  var fromVal = elFromDate.value;
  var vFrom = validateFromDate(fromVal);
  setFieldError(elFromDate, elFromErr, vFrom.error);

  if (!vFrom.ok) {
    elContent.innerHTML = '<div class="result-hint">Enter a valid calculate-from date to see the team.</div>';
    return;
  }

  if (memberRows.length === 0) {
    elContent.innerHTML = '<div class="result-hint">Add team members to see who&rsquo;s at risk.</div>';
    return;
  }

  var rows = memberRows.map(function (m) {
    return { name: m.name, required: m.required, earned: m.earned, endDate: m.endDate };
  });
  var ranked = rankTeam(rows, fromVal);

  var valid   = ranked.filter(function (r) { return r.badge !== 'Incomplete' && r.badge !== 'Invalid'; });
  var danger  = ranked.filter(function (r) { return r.badge === 'At risk' || r.badge === 'Lapsed'; });

  var html = '';
  ranked.forEach(function (item) {
    html += '<div class="team-result-row">'
      + '<span class="team-badge ' + badgeClass(item.badge) + '">' + esc(item.badge) + '</span>'
      + '<div class="team-result-body">'
      + '<div class="team-result-name">' + esc(item.displayName) + '</div>'
      + resultLine(item)
      + '</div></div>';
  });

  var summary;
  if (valid.length === 0) {
    summary = 'Add team members to see who’s at risk.';
  } else {
    summary = danger.length + ' of ' + valid.length + ' at risk or lapsed';
  }
  html += '<div class="team-summary">' + esc(summary) + '</div>';

  elContent.innerHTML = html;
}

// ── Build a member row element ──────────────────────────────────────────

function buildRowEl(m, index) {
  var div = document.createElement('div');
  div.className = 'team-row';
  div.dataset.id = m.id;

  var presetOptions = ''
    + '<option value="">Custom</option>'
    + '<option value="60">SHRM-CP / SHRM-SCP</option>'
    + '<option value="60">HRCI PHR / SPHR</option>'
    + '<option value="60">PMI PMP</option>'
    + '<option value="15">PMI CAPM</option>';

  var nameId     = 'tm-name-'    + m.id;
  var presetId   = 'tm-preset-'  + m.id;
  var requiredId = 'tm-req-'     + m.id;
  var earnedId   = 'tm-earn-'    + m.id;
  var endDateId  = 'tm-end-'     + m.id;

  div.innerHTML = ''
    + '<div class="team-row-fields">'
    + '  <div class="form-group"><label for="' + nameId + '">Name <span class="optional">(optional)</span></label>'
    + '    <input type="text" id="' + nameId + '" placeholder="Person ' + (index + 1) + '" autocomplete="off"></div>'
    + '  <div class="form-group"><label for="' + presetId + '">Preset</label>'
    + '    <select id="' + presetId + '">' + presetOptions + '</select></div>'
    + '  <div class="form-group"><label for="' + requiredId + '">Credits required</label>'
    + '    <input type="text" id="' + requiredId + '" inputmode="decimal" placeholder="e.g. 60" autocomplete="off"></div>'
    + '  <div class="form-group"><label for="' + earnedId + '">Credits earned</label>'
    + '    <input type="text" id="' + earnedId + '" inputmode="decimal" placeholder="0" autocomplete="off"></div>'
    + '  <div class="form-group"><label for="' + endDateId + '">Cycle end date</label>'
    + '    <input type="date" id="' + endDateId + '" min="2000-01-01" max="2100-12-31"></div>'
    + '</div>'
    + '<button class="btn-remove" type="button" aria-label="Remove member">&times;</button>';

  var nameEl    = div.querySelector('#' + nameId);
  var presetEl  = div.querySelector('#' + presetId);
  var reqEl     = div.querySelector('#' + requiredId);
  var earnEl    = div.querySelector('#' + earnedId);
  var endEl     = div.querySelector('#' + endDateId);
  var removeBtn = div.querySelector('.btn-remove');

  var suppressPreset = false;

  function sync() {
    m.name     = nameEl.value;
    m.required = reqEl.value;
    m.earned   = earnEl.value;
    m.endDate  = endEl.value;
    renderResults();
  }

  presetEl.addEventListener('change', function () {
    if (this.value !== '') {
      suppressPreset = true;
      reqEl.value = this.value;
      suppressPreset = false;
    }
    sync();
  });

  reqEl.addEventListener('input', function () {
    if (!suppressPreset) presetEl.value = '';
    sync();
  });

  nameEl.addEventListener('input', sync);
  earnEl.addEventListener('input', sync);
  endEl.addEventListener('change', sync);

  removeBtn.addEventListener('click', function () {
    memberRows = memberRows.filter(function (r) { return r.id !== m.id; });
    rebuildList();
    renderResults();
  });

  return div;
}

// ── Rebuild the full member list DOM ────────────────────────────────────

function rebuildList() {
  elList.innerHTML = '';
  memberRows.forEach(function (m, i) {
    elList.appendChild(buildRowEl(m, i));
  });
  elAddBtn.disabled = memberRows.length >= MAX_MEMBERS;
}

content.thinking:
Now I can see the two bugs clearly:

**Bug 1**: In `buildRowEl`, the input values are never restored from `m`. After `div.innerHTML = ...`, when elements are queried, their values are always empty. The fix is to set their values from `m` after querying:

```js
nameEl.value   = m.name     || '';
presetEl.value = m.preset   || '';
reqEl.value    = m.required || '';
earnEl.value   = m.earned   || '';
endEl.value    = m.endDate  || '';
```

Also need to track `m.preset` - add it to the model, and sync it in event handlers.
Now I'm describing the second bug, where the summary is appended after the rows when it should go first. I plan to prepend it. I also need to track the preset in `sync()`: set it when the preset changes, and clear it when the required field is edited directly.

The model needs a `preset` field too, initialized to an empty string. Removing a row only has to rebuild from state, which already restores the other rows' values. Adding a row could just append its element instead, but restoring from state is simpler and works just as well, so I'll keep that.

I'm listing the changes to make: seed `preset` in the initial model, restore the input values from `m` in `buildRowEl`, update `m.preset` in the preset and required-field handlers, and move the summary to the top of the rendered HTML.

